/**
 * @description Tests for Preview payload (outbound Selected Fields and Apex Class, inbound, record not found, admins
 * only) and View request (attempts, Files, rerun offer, readers who can see the transaction).
 */
@IsTest
private class IntegrationHubPreviewTest {

    @TestSetup
    static void setup() {
        IntegrationHubTestData.setupAll();
    }

    private static Map<String, Object> parse(String body) {
        return (Map<String, Object>) JSON.deserializeUntyped(body);
    }

    @IsTest
    static void selectedFieldsPreviewIsBuiltLikeASend() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Connection__c rec = IntegrationHubTestData.accounts()[0];
            IntegrationHubPreview.Preview p = IntegrationHubPreview.previewPayload(
                IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Id, ' ' + rec.Id + ' ');
            Assert.isNull(p.message, 'the body was built: ' + p.message);
            Assert.areEqual('Selected Fields', p.bodySource, 'the source is named');
            Assert.areEqual('POST', p.method, 'the event method');
            Assert.areEqual('callout:IH_Test/records/' + rec.Id, p.url, 'the Named Credential and the filled path');
            Assert.areEqual('Test system', p.connectionName, 'the connection is named');
            Map<String, Object> body = parse(p.body);
            Assert.areEqual('PREVIEW', body.get('sfTransactionId'), 'the transaction Id is PREVIEW');
            Assert.areEqual('Record One', ((Map<String, Object>) body.get('fields')).get('Name'), 'the selected fields are filled');
            Assert.isTrue(p.body.contains('\n'), 'the body is pretty-printed');
            Assert.areEqual('Content-Type', p.headers[0].name, 'the headers are listed');
            Assert.isFalse(p.expectsCallback, 'no callback for this event');
            Assert.areEqual(0, [SELECT COUNT() FROM IH_Transaction__c WITH SYSTEM_MODE], 'nothing is saved');
        }
    }

    @IsTest
    static void apexClassPreviewAndCallback() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Event__c ev = IntegrationHubTestData.newApexClassEvent(IntegrationHubTestData.CLASS_KEY);
            ev.Expects_Callback__c = true;
            ev.Business_Data_In_Response__c = true;
            ev.Response_Handler_Class__c = 'IntegrationHubTestData.StubBusiness';
            IntegrationHubData.updateAll(new List<IH_Event__c>{ ev });
            IntegrationHubPreview.Preview p = IntegrationHubPreview.previewPayload(ev.Id, IntegrationHubTestData.accounts()[0].Id);
            Assert.areEqual('Apex Class: IntegrationHubTestData.StubPayloadBuilder', p.bodySource, 'the class is named');
            Map<String, Object> body = parse(p.body);
            Assert.areEqual('map', body.get('kind'), 'the class built the body');
            Assert.areEqual('PREVIEW', body.get('sfTransactionId'), 'the transaction Id key is PREVIEW');
            Assert.isTrue(p.expectsCallback, 'the callback is described');
            Assert.areEqual(24, p.callbackHours, 'within the event timeout');
            Assert.isTrue(p.callbackUrl.endsWith('callback/{sfTransactionId}'), 'the callback URL');
            Assert.isTrue(parse(p.callbackBody).containsKey('data'), 'the data envelope is shown for business data');
            Assert.isTrue(p.businessData, 'the event flag is returned');
        }
    }

    @IsTest
    static void recordNotFoundAndCaseNumber() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Event__c caseEvent = new IH_Event__c(Name = 'Case preview', Event_Key__c = 'CASE_PREVIEW', Direction__c = 'Outbound',
                Related_Object__c = 'Case', Path__c = '/cases/{recordId}', Connection__c = IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Connection__c);
            IntegrationHubData.insertAll(new List<IH_Event__c>{ caseEvent });
            IntegrationHubPreview.Preview missing = IntegrationHubPreview.previewPayload(caseEvent.Id, '99999999');
            Assert.isNull(missing.body, 'no body without a record');
            Assert.isTrue(missing.message.contains('No Case record found'), 'the problem is explained: ' + missing.message);
            Assert.isTrue(missing.url.endsWith('/cases/{recordId}'), 'the path keeps the placeholder');
            IntegrationHubPreview.Preview blank = IntegrationHubPreview.previewPayload(caseEvent.Id, '');
            Assert.isTrue(blank.message.contains('Id or its name'), 'a record Id or its name may be entered: ' + blank.message);
            Assert.areEqual('Event not found.', IntegrationHubPreview.previewPayload(null, 'x').message, 'no event');
        }
    }

    @IsTest
    static void inboundPreviewShowsTheCallToMake() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            Id inboundId = IntegrationHubTestData.eventByKey(IntegrationHubTestData.IN_KEY).Id;
            IntegrationHubPreview.Preview template = IntegrationHubPreview.previewPayload(inboundId, null);
            Assert.areEqual('/services/apexrest/integrationhub/v1/' + IntegrationHubTestData.IN_KEY, template.url, 'the REST path');
            Assert.areEqual(3, template.headers.size(), 'Authorization, Content-Type and X-Request-Id');
            Assert.isTrue(parse(template.body).containsKey('fields'), 'a body template');
            IntegrationHubPreview.Preview sample = IntegrationHubPreview.previewPayload(inboundId, IntegrationHubTestData.accounts()[0].Id);
            Assert.isNull(sample.message, 'the record was found: ' + sample.message);
            Assert.isTrue(sample.bodySource.startsWith('Sample from '), 'the sample source is named');
            Assert.isTrue(sample.body.contains('Record One'), 'the body is filled from the record');
        }
    }

    @IsTest
    static void previewIsForAdminsOnly() {
        System.runAs(IntegrationHubTestData.reader()) {
            try {
                IntegrationHubPreview.previewPayload(null, null);
                Assert.fail('a reader cannot preview');
            } catch (AuraHandledException e) {
                Assert.isTrue(e.getMessage().contains('Admin'), 'the error names the permission');
            }
        }
    }

    @IsTest
    static void exchangeShowsAttemptsFilesAndRerun() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Transaction__c t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Success');
            IntegrationHubData.updateAll(new List<IH_Transaction__c>{ new IH_Transaction__c(Id = t.Id, Business_Status__c = 'Failed',
                Business_Error__c = 'boom', Request_Url__c = 'POST callout:IH_Test/records/1', Http_Status_Code__c = 200,
                Response_Body__c = 'x'.repeat(131072), Correlation_Id__c = 'corr-9') });
            IntegrationHubData.insertAll(new List<IH_Attempt__c>{
                new IH_Attempt__c(Transaction__c = t.Id, Attempted_At__c = System.now(), Outcome__c = 'Success', Http_Status_Code__c = 200,
                    Kind__c = 'Send', Payload_Used__c = 'Original') });
            IntegrationHubBodyFiles.save(new List<ContentVersion>{
                IntegrationHubBodyFiles.fileFor(t.Id, IntegrationHubBodyFiles.RESPONSE_PREFIX + 'IT-1', 'y'.repeat(131073)) });
            IntegrationHubPreview.Exchange x = IntegrationHubPreview.getExchange(t.Id);
            Assert.areEqual('Test system', x.connectionName, 'the connection is named');
            Assert.areEqual('POST callout:IH_Test/records/1', x.requestUrl, 'the request line');
            Assert.isTrue(x.requestBody.contains('"stored"'), 'the request body');
            Assert.areEqual('corr-9', x.requestHeaders[1].value, 'the correlation Id is shown');
            Assert.isTrue(x.responseCut, 'a full field is marked as cut');
            Assert.isNotNull(x.responseFileId, 'the File with the full answer is found');
            Assert.isNull(x.callbackFileId, 'no callback File');
            Assert.areEqual(1, x.attempts.size(), 'the attempts are listed');
            Assert.areEqual(1, x.attempts[0].n, 'numbered from 1');
            Assert.areEqual('Send', x.attempts[0].kind, 'the kind is shown');
            Assert.isTrue(x.businessData, 'business processing is shown when there is a Business Status');
            Assert.isTrue(x.canRerun, 'an admin can rerun a Failed handler');
        }
    }

    @IsTest
    static void readerSeesSharedTransactionsWithoutRerun() {
        IH_Transaction__c t;
        IH_Transaction__c hidden;
        User reader = IntegrationHubTestData.reader();
        System.runAs(IntegrationHubTestData.admin()) {
            t = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            hidden = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IntegrationHubData.updateAll(new List<IH_Transaction__c>{ new IH_Transaction__c(Id = t.Id, Business_Status__c = 'Failed') });
            IntegrationHubData.insertAll(new List<IH_Transaction__Share>{
                new IH_Transaction__Share(ParentId = t.Id, UserOrGroupId = reader.Id, AccessLevel = 'Read') });
        }
        System.runAs(reader) {
            IntegrationHubPreview.Exchange x = IntegrationHubPreview.getExchange(t.Id);
            Assert.areEqual(t.Id, x.transactionId, 'a shared transaction can be opened');
            Assert.isFalse(x.canRerun, 'only admins are offered Rerun');
            Assert.areEqual(IntegrationHubExchange.HIDDEN, x.requestBody, 'readers do not see the bodies');
            try {
                IntegrationHubPreview.getExchange(hidden.Id);
                Assert.fail('a transaction the reader cannot see is refused');
            } catch (AuraHandledException e) {
                Assert.isTrue(e.getMessage().contains('cannot open'), 'the refusal is explained');
            }
        }
    }

    @IsTest
    static void inboundExchangeShowsTheCallReceived() {
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Event__c ev = IntegrationHubTestData.eventByKey(IntegrationHubTestData.IN_KEY);
            IH_Transaction__c t = new IH_Transaction__c(Event__c = ev.Id, Event_Name__c = IntegrationHubTestData.IN_KEY,
                Direction__c = 'Inbound', Status__c = 'Success', Request_Id__c = 'req-9', Request_Payload__c = '{"name":"A"}',
                Response_Body__c = '{"status":"Success"}', Http_Status_Code__c = 200);
            IntegrationHubData.insertAll(new List<IH_Transaction__c>{ t });
            IntegrationHubPreview.Exchange x = IntegrationHubPreview.getExchange(t.Id);
            Assert.areEqual('POST /services/apexrest/integrationhub/v1/' + IntegrationHubTestData.IN_KEY, x.requestUrl, 'the call received');
            Assert.areEqual('req-9', x.requestHeaders[1].value, 'the X-Request-Id is shown');
            Assert.isFalse(x.canRerun, 'nothing to rerun');
            Assert.areEqual(0, x.attempts.size(), 'no attempts');
            Assert.areEqual('{"a":1}', IntegrationHubExchange.pretty('{"a":1}').deleteWhitespace(), 'JSON is pretty-printed');
            Assert.areEqual('not json', IntegrationHubExchange.pretty('not json'), 'other text is kept');
        }
    }
}
